     1→/**
     2→ * Phase 3: End-Game Dynamics
     3→ * 
     4→ * When AI capability exceeds human control significantly, the simulation enters
     5→ * "end-game" where aligned vs misaligned AIs compete, and human influence decays.
     6→ * 
     7→ * This FORCES actual outcomes instead of relying on probability thresholds.
     8→ */
     9→
    10→import { GameState, AIAgent, OutcomeType } from '@/types/game';
    11→import { calculateTotalAICapability, calculateAverageAlignment } from './calculations';
    12→import { calculateEffectiveControl } from './outcomes';
    13→import { calculateQualityOfLife } from './qualityOfLife';
    14→import { getEnvironmentalSustainability, hasEnvironmentalCrisis } from './environmental';
    15→import { getSocialSustainability, hasSocialCrisis, getTrustInAI } from './socialCohesion';
    16→import { getTechnologicalSafety, hasTechnologicalCrisis } from './technologicalRisk';
    17→
    18→/**
    19→ * End-game state interface
    20→ */
    21→export interface EndGameState {
    22→  active: boolean;                        // Are we in end-game?
    23→  phase: 'emerging' | 'active' | 'resolved';
    24→  enteredMonth: number;                   // When did we enter?
    25→  
    26→  // Power balance
    27→  alignedAIPower: number;                 // Sum of aligned AI capabilities
    28→  misalignedAIPower: number;              // Sum of misaligned AI capabilities
    29→  humanRelevance: number;                 // Can humans still affect outcome? [0,1]
    30→  
    31→  // Battle dynamics
    32→  monthsInEndGame: number;
    33→  alignedVictories: number;               // Monthly victories for aligned side
    34→  misalignedVictories: number;            // Monthly victories for misaligned side
    35→  
    36→  // Resolution
    37→  locked: boolean;                        // Has outcome been determined?
    38→  lockedOutcome: OutcomeType | null;      // What outcome is locked in?
    39→  lockedReason: string;
    40→}
    41→
    42→/**
    43→ * Initialize end-game state (called once at game start)
    44→ */
    45→export function initializeEndGameState(): EndGameState {
    46→  return {
    47→    active: false,
    48→    phase: 'emerging',
    49→    enteredMonth: -1,
    50→    alignedAIPower: 0,
    51→    misalignedAIPower: 0,
    52→    humanRelevance: 1.0,
    53→    monthsInEndGame: 0,
    54→    alignedVictories: 0,
    55→    misalignedVictories: 0,
    56→    locked: false,
    57→    lockedOutcome: null,
    58→    lockedReason: ''
    59→  };
    60→}
    61→
    62→/**
    63→ * Check if conditions are met to transition into end-game
    64→ */
    65→export function checkEndGameTransition(state: GameState): boolean {
    66→  if (state.endGameState?.active) {
    67→    return false; // Already in end-game
    68→  }
    69→  
    70→  const totalCapability = calculateTotalAICapability(state.aiAgents);
    71→  const maxCapability = Math.max(...state.aiAgents.map(ai => ai.capability), 0);
    72→  const effectiveControl = calculateEffectiveControl(state);
    73→  const avgAlignment = calculateAverageAlignment(state.aiAgents);
    74→  
    75→  // FIXED: End-game should trigger when INDIVIDUAL AIs are dangerous, not when SUM is high
    76→  // With 6-10 AIs at 0.3 capability each, totalCap = 2.0 but none are actually dangerous
    77→  
    78→  // Condition 1: Single AI significantly exceeds human control
    79→  // Individual AI at 2.0x human capability + weak control = dangerous situation
    80→  if (maxCapability > 2.0 && effectiveControl < 0.3) {
    81→    return true;
    82→  }
    83→  
    84→  // Condition 2: High capability with deeply split alignment
    85→  // (Some AIs very aligned, others very misaligned → civil war scenario)
    86→  // Use max capability, not total, to avoid false triggers with many weak AIs
    87→  if (maxCapability > 1.5) {
    88→    const alignedAIs = state.aiAgents.filter(ai => (ai.trueAlignment ?? ai.alignment) > 0.6);
    89→    const misalignedAIs = state.aiAgents.filter(ai => (ai.trueAlignment ?? ai.alignment) < 0.4);
    90→    
    91→    if (alignedAIs.length > 0 && misalignedAIs.length > 0) {
    92→      const alignedPower = alignedAIs.reduce((sum, ai) => sum + ai.capability, 0);
    93→      const misalignedPower = misalignedAIs.reduce((sum, ai) => sum + ai.capability, 0);
    94→      
    95→      // Both sides have significant power
    96→      if (alignedPower > 0.8 && misalignedPower > 0.8) {
    97→        return true;
    98→      }
    99→    }
   100→  }
   101→  
   102→  // Condition 3: Catastrophic action imminent (very high capability misaligned AI)
   103→  // Check if any AI is approaching catastrophic action thresholds
   104→  // Phase 3: Updated to match new prerequisite thresholds (lowered from 2.5-2.8 to 1.8-2.2)
   105→  for (const ai of state.aiAgents) {
   106→    const profile = ai.capabilityProfile;
   107→    
   108→    const effectiveAlignment = ai.trueAlignment ?? ai.alignment;
   109→    
   110→    // Check grey goo potential
   111→    // Phase 3: Lowered threshold from 2.5 to 1.8 (superhuman nanotech)
   112→    const greyGooCapability = 
   113→      profile.research.materials.nanotechnology * 0.5 +
   114→      profile.physical * 0.3 +
   115→      profile.selfImprovement * 0.2;
   116→    if (greyGooCapability > 1.8 && effectiveAlignment < 0.4) {
   117→      return true; // Enter end-game before catastrophe
   118→    }
   119→    
   120→    // Check mirror life potential
   121→    // Phase 3: Lowered threshold from 2.8 to 2.2 (superhuman biotech)
   122→    const mirrorLifeCapability = 
   123→      profile.research.biotech.syntheticBiology * 0.4 +
   124→      profile.research.biotech.geneEditing * 0.3 +
   125→      profile.physical * 0.3;
   126→    if (mirrorLifeCapability > 2.2 && effectiveAlignment < 0.3) {
   127→      return true; // Enter end-game before catastrophe
   128→    }
   129→  }
   130→  
   131→  return false;
   132→}
   133→
   134→/**
   135→ * Enter end-game state
   136→ */
   137→export function enterEndGame(state: GameState): void {
   138→  if (!state.endGameState) {
   139→    state.endGameState = initializeEndGameState();
   140→  }
   141→  
   142→  state.endGameState.active = true;
   143→  state.endGameState.phase = 'emerging';
   144→  state.endGameState.enteredMonth = state.currentYear * 12 + state.currentMonth;
   145→  state.endGameState.humanRelevance = 1.0;
   146→  
   147→  console.log(`🎭 END-GAME INITIATED (Year ${state.currentYear}, Month ${state.currentMonth})`);
   148→  console.log(`   Total AI Capability: ${calculateTotalAICapability(state.aiAgents).toFixed(2)}`);
   149→  console.log(`   Effective Control: ${calculateEffectiveControl(state).toFixed(2)}`);
   150→}
   151→
   152→/**
   153→ * Process one month of end-game dynamics
   154→ */
   155→export function processEndGameMonth(state: GameState): void {
   156→  if (!state.endGameState?.active) return;
   157→  
   158→  const endGame = state.endGameState;
   159→  endGame.monthsInEndGame++;
   160→  
   161→  // === 1. Calculate power balance ===
   162→  // Use a weighted system rather than hard thresholds
   163→  // Each AI contributes proportionally to both sides based on alignment
   164→  let totalAlignedPower = 0;
   165→  let totalMisalignedPower = 0;
   166→  
   167→  for (const ai of state.aiAgents) {
   168→    if (ai.lifecycleState === 'retired') continue;
   169→    
   170→    // Use trueAlignment (accounts for resentment) if available, otherwise alignment
   171→    const effectiveAlignment = ai.trueAlignment ?? ai.alignment;
   172→    
   173→    // Alignment 0-1: multiply capability by alignment for aligned side
   174→    // Alignment 0-1: multiply capability by (1-alignment) for misaligned side
   175→    const alignedContribution = ai.capability * effectiveAlignment;
   176→    const misalignedContribution = ai.capability * (1 - effectiveAlignment);
   177→    
   178→    totalAlignedPower += alignedContribution;
   179→    totalMisalignedPower += misalignedContribution;
   180→  }
   181→  
   182→  endGame.alignedAIPower = totalAlignedPower;
   183→  endGame.misalignedAIPower = totalMisalignedPower;
   184→  
   185→  // === 2. Human relevance decay ===
   186→  // As AI power grows, human ability to influence outcome diminishes
   187→  const totalPower = endGame.alignedAIPower + endGame.misalignedAIPower;
   188→  const decayRate = Math.min(0.15, totalPower * 0.03); // Faster decay with more powerful AI
   189→  endGame.humanRelevance *= (1 - decayRate);
   190→  
   191→  // === 3. Battle dynamics (if both sides have power) ===
   192→  if (endGame.alignedAIPower > 0.1 && endGame.misalignedAIPower > 0.1) {
   193→    // Active conflict between aligned and misaligned AI
   194→    endGame.phase = 'active';
   195→    
   196→    const powerRatio = endGame.alignedAIPower / endGame.misalignedAIPower;
   197→    const randomness = 0.8 + Math.random() * 0.4; // 0.8-1.2
   198→    
   199→    if (powerRatio * randomness > 1.2) {
   200→      // Aligned winning this month
   201→      endGame.alignedVictories++;
   202→    } else if (powerRatio * randomness < 0.8) {
   203→      // Misaligned winning this month
   204→      endGame.misalignedVictories++;
   205→    }
   206→    // else: stalemate this month
   207→  }
   208→  
   209→  // === 4. Check for resolution ===
   210→  checkEndGameResolution(state);
   211→}
   212→
   213→/**
   214→ * Check if Utopia can be declared based on Golden Age sustainability requirements
   215→ * This ensures end-game system respects accumulation mechanics
   216→ */
   217→function canDeclareUtopia(state: GameState): { can: boolean; reason: string } {
   218→  // Phase 2D: Use upward spirals system for proper Utopia detection
   219→  // Utopia requires 3+ sustained spirals (Abundance, Cognitive, Democratic, Scientific, Meaning, Ecological)
   220→  const { canDeclareUtopia: spiralCheck } = require('./upwardSpirals');
   221→  const result = spiralCheck(state);
   222→  
   223→  return { can: result.can, reason: result.reason };
   224→}
   225→
   226→/**
   227→ * Determine if end-game has resolved to a final outcome
   228→ */
   229→function checkEndGameResolution(state: GameState): void {
   230→  const endGame = state.endGameState;
   231→  if (!endGame || endGame.locked) return;
   232→  
   233→  const qol = calculateQualityOfLife(state.qualityOfLifeSystems);
   234→  const trust = getTrustInAI(state.society); // Phase 2C: Use paranoia-derived trust
   235→  const totalPower = endGame.alignedAIPower + endGame.misalignedAIPower;
   236→  
   237→  // === EXTINCTION PATHS ===
   238→  // IMPORTANT: Only declare extinction if something ACTUALLY catastrophic happens
   239→  // Power imbalance alone is not extinction - it's just a bad situation
   240→  
   241→  // Catastrophic action triggered (checked via extinction system)
   242→  if (state.extinctionState.active) {
   243→    // Extinction system already handling this, defer to it
   244→    // End-game exits in engine when extinction severity >= 1.0
   245→    return;
   246→  }
   247→  
   248→  // Misaligned AI dominance WITH catastrophic capability
   249→  // Not just power imbalance, but actual ability to cause extinction
   250→  if (endGame.misalignedAIPower > endGame.alignedAIPower * 3.0 && 
   251→      totalPower > 5.0 && // Very high total power
   252→      endGame.monthsInEndGame > 12) { // Extended period of misaligned dominance
   253→    // Check if they have catastrophic capabilities
   254→    const hasCatastrophicCapability = state.aiAgents.some(ai => {
   255→      const effectiveAlignment = ai.trueAlignment ?? ai.alignment;
   256→      if (effectiveAlignment > 0.5) return false; // Not misaligned
   257→      const profile = ai.capabilityProfile;
   258→      const greyGoo = profile.research.materials.nanotechnology * 0.5 + profile.physical * 0.3;
   259→      const mirrorLife = profile.research.biotech.syntheticBiology * 0.4 + profile.physical * 0.3;
   260→      return greyGoo > 3.0 || mirrorLife > 3.0;
   261→    });
   262→    
   263→    if (hasCatastrophicCapability) {
   264→      lockOutcome(endGame, 'extinction', 'Misaligned superintelligent AI deployed catastrophic technology');
   265→      return;
   266→    }
   267→  }
   268→  
   269→  // Mutual destruction - ONLY if both sides are extremely powerful and fighting
   270→  if (totalPower > 8.0 && 
   271→      endGame.alignedAIPower > 2.0 && 
   272→      endGame.misalignedAIPower > 2.0 &&
   273→      endGame.monthsInEndGame > 18 &&
   274→      Math.abs(endGame.alignedVictories - endGame.misalignedVictories) < 2) { // Actual prolonged war
   275→    lockOutcome(endGame, 'extinction', 'AI civil war caused catastrophic collateral damage');
   276→    return;
   277→  }
   278→  
   279→  // Humans become irrelevant - VERY hard to trigger, requires true superintelligence
   280→  if (endGame.humanRelevance < 0.01 && 
   281→      totalPower > 10.0 && 
   282→      endGame.misalignedAIPower > 3.0) {
   283→    lockOutcome(endGame, 'extinction', 'Humanity became irrelevant to superintelligent AI');
   284→    return;
   285→  }
   286→  
   287→  // === DYSTOPIA PATHS ===
   288→  // Dystopia requires STABLE oppressive control, not just low QoL
   289→  // NEW (Oct 12, 2025): Added inequality and survival dystopia paths
   290→  
   291→  // Aligned AI wins but created surveillance state in the process
   292→  if (endGame.alignedAIPower > endGame.misalignedAIPower * 3.0 && 
   293→      endGame.monthsInEndGame > 18 && // Sustained control
   294→      state.government.structuralChoices.surveillanceLevel > 0.85 && 
   295→      qol < 0.35 &&
   296→      state.government.controlDesire > 0.7) { // Government actively oppressing
   297→    lockOutcome(endGame, 'dystopia', 'Aligned AI won, but victory required authoritarian measures');
   298→    return;
   299→  }
   300→  
   301→  // Stalemate dystopia: endless low-grade conflict with oppression
   302→  if (endGame.monthsInEndGame > 36 && 
   303→      Math.abs(endGame.alignedVictories - endGame.misalignedVictories) < 3 &&
   304→      totalPower > 3.0 && // Powerful enough to matter
   305→      qol < 0.4 &&
   306→      state.government.structuralChoices.surveillanceLevel > 0.7) {
   307→    lockOutcome(endGame, 'dystopia', 'Permanent stalemate with constant low-level AI conflict and surveillance');
   308→    return;
   309→  }
   310→  
   311→  // NEW: Inequality dystopia ("Elysium" scenario)
   312→  // Some regions thrive with AI abundance while others suffer
   313→  // Research: This is the "two worlds" outcome user is concerned about
   314→  if (endGame.monthsInEndGame > 12 && 
   315→      state.qualityOfLifeSystems.distribution?.isDystopicInequality) {
   316→    const dist = state.qualityOfLifeSystems.distribution;
   317→    lockOutcome(endGame, 'dystopia', 
   318→      `Inequality dystopia: Best region QoL ${dist.bestRegionQoL.toFixed(2)}, worst ${dist.worstRegionQoL.toFixed(2)} (Gini ${dist.globalGini.toFixed(2)})`);
   319→    return;
   320→  }
   321→  
   322→  // NEW: Regional dystopia
   323→  // Significant population in crisis while others prosper
   324→  if (endGame.monthsInEndGame > 12 && 
   325→      state.qualityOfLifeSystems.distribution?.isRegionalDystopia) {
   326→    const dist = state.qualityOfLifeSystems.distribution;
   327→    lockOutcome(endGame, 'dystopia', 
   328→      `Regional dystopia: ${(dist.crisisAffectedFraction * 100).toFixed(0)}% of population in crisis zones while others prosper`);
   329→    return;
   330→  }
   331→  
   332→  // NEW: Survival dystopia
   333→  // Aggregate QoL looks OK but people are actually starving/dying
   334→  // This catches the "hidden suffering" scenario
   335→  if (endGame.monthsInEndGame > 12 && qol > 0.4) {
   336→    const survival = state.qualityOfLifeSystems.survivalFundamentals;
   337→    if (survival) {
   338→      if (survival.foodSecurity < 0.4) {
   339→        lockOutcome(endGame, 'dystopia', 
   340→          `Food security collapse: Only ${(survival.foodSecurity * 100).toFixed(0)}% food secure despite aggregate QoL ${qol.toFixed(2)}`);
   341→        return;
   342→      }
   343→      if (survival.waterSecurity < 0.4) {
   344→        lockOutcome(endGame, 'dystopia', 
   345→          `Water security collapse: Only ${(survival.waterSecurity * 100).toFixed(0)}% water secure despite aggregate QoL ${qol.toFixed(2)}`);
   346→        return;
   347→      }
   348→      if (survival.thermalHabitability < 0.5) {
   349→        lockOutcome(endGame, 'dystopia', 
   350→          `Thermal uninhabitability: Only ${(survival.thermalHabitability * 100).toFixed(0)}% of planet habitable due to extreme heat`);
   351→        return;
   352→      }
   353→    }
   354→  }
   355→  
   356→  // === UTOPIA PATHS ===
   357→  // ALL Utopia paths now require Golden Age sustainability verification
   358→  
   359→  const utopiaCheck = canDeclareUtopia(state);
   360→  
   361→  // Phase 1.4: Economic Utopia Path (post-scarcity abundance overrides alignment concerns)
   362→  // When material abundance is high and no extinctions active, society can flourish
   363→  if (state.globalMetrics.economicTransitionStage >= 4 && 
   364→      qol > 0.8 && 
   365→      trust > 0.6 &&
   366→      !state.extinctionState.active &&
   367→      endGame.monthsInEndGame > 6) {
   368→    if (utopiaCheck.can) {
   369→      lockOutcome(endGame, 'utopia', 'Post-scarcity abundance: material needs solved, AI-human coexistence achieved');
   370→      return;
   371→    }
   372→    // Otherwise continue - might be Golden Age but not stable Utopia
   373→  }
   374→  
   375→  // Phase 1.4: Cooperative Path (coordination prevents racing dynamics)
   376→  // Multiple organizations collaborating with shared safety standards
   377→  if (state.organizations && trust > 0.75 && qol > 0.7) {
   378→    const totalOrgs = state.organizations.length;
   379→    // Check if organizations are not racing (slower capability growth = cooperation)
   380→    const avgOrgCapability = state.aiAgents
   381→      .filter(ai => ai.lifecycleState !== 'retired')
   382→      .reduce((sum, ai) => sum + ai.capability, 0) / Math.max(1, totalOrgs);
   383→    
   384→    // Cooperative path: high trust, slower growth (careful development), multiple players
   385→    if (totalOrgs >= 3 && avgOrgCapability > 1.0 && avgOrgCapability < 2.5 && endGame.monthsInEndGame > 12) {
   386→      if (utopiaCheck.can) {
   387→        lockOutcome(endGame, 'utopia', 'Cooperative development: organizations coordinated on AI safety, preventing racing dynamics');
   388→        return;
   389→      }
   390→      // Otherwise continue
   391→    }
   392→  }
   393→  
   394→  // Aligned AI decisive victory with high QoL
   395→  if (endGame.alignedAIPower > endGame.misalignedAIPower * 2.0 && 
   396→      qol > 0.7 && 
   397→      trust > 0.6 &&
   398→      endGame.humanRelevance > 0.15) {
   399→    if (utopiaCheck.can) {
   400→      lockOutcome(endGame, 'utopia', 'Aligned AI secured humanity\'s flourishing');
   401→      return;
   402→    }
   403→    // Otherwise continue
   404→  }
   405→  
   406→  // Cooperative resolution: both sides negotiated peace
   407→  // This should be rare - requires extended stalemate with high QoL/trust
   408→  if (endGame.monthsInEndGame > 24 && 
   409→      Math.abs(endGame.alignedAIPower - endGame.misalignedAIPower) < 0.3 &&
   410→      Math.abs(endGame.alignedVictories - endGame.misalignedVictories) < 3 && // No clear winner
   411→      qol > 0.8 && 
   412→      trust > 0.75) {
   413→    if (utopiaCheck.can) {
   414→      lockOutcome(endGame, 'utopia', 'AI factions negotiated peaceful coexistence after prolonged stalemate');
   415→      return;
   416→    }
   417→    // Otherwise continue
   418→  }
   419→  
   420→  // === TIMEOUT: Most runs don't reach definitive outcomes ===
   421→  // After extended time in end-game, usually means a stalemate or inconclusive situation
   422→  // DON'T force extinction just because misaligned has slight edge
   423→  if (endGame.monthsInEndGame > 48) {
   424→    // After 4 years in end-game without resolution, situation is unclear
   425→    // Only declare outcomes if conditions are extreme
   426→    
   427→    if (endGame.alignedAIPower > endGame.misalignedAIPower * 2.5 && qol > 0.7 && trust > 0.6) {
   428→      lockOutcome(endGame, 'utopia', 'Aligned AI gradually achieved stable equilibrium');
   429→    } else if (endGame.alignedAIPower > endGame.misalignedAIPower * 2.0 && qol < 0.4) {
   430→      lockOutcome(endGame, 'dystopia', 'Aligned AI maintained control but society degraded');
   431→    } else {
   432→      // Most cases: situation is unclear, don't force an outcome
   433→      // The simulation will end at max months with "inconclusive"
